function transfer(address _to, uint256 _value, bytes _data, string _customFallback) public returns (bool success) {
ttif (isContract(_to)) {
tttrequire(_to != address(0x0));
tttrequire(balances[msg.sender] >= _value);
tttbalances[msg.sender] -= _value;
tttbalances[_to] += _value;
tttassert(_to.call.value(0)(bytes4(keccak256(_customFallback)), msg.sender, _value, _data));
tttTransfer(msg.sender, _to, _value);
tttTransfer(msg.sender, _to, _value, _data);
tttreturn true;
tt} else {
tttreturn transferToAddress(_to, _value, _data);
tt}
t}

function transferToContract(address _to, uint256 _value, bytes _data) private returns (bool success) {
ttrequire(_to != address(0x0));
ttrequire(balances[msg.sender] >= _value);
ttbalances[msg.sender] -= _value;
ttbalances[_to] += _value;
ttERC223Receiver receiver = ERC223Receiver(_to);
ttreceiver.tokenFallback(msg.sender, _value, _data);
ttTransfer(msg.sender, _to, _value);
ttTransfer(msg.sender, _to, _value, _data);
ttreturn true;
t}

